/* Published JavaScript that declares class fields for typings only, the shape
 * svelte 4's `src/runtime/internal/dev.js` ships: the fields carry a JSDoc
 * type, no initializer, and are never read at run time. Checking the file
 * reports TS2564 for each one. */
export class Widget {
	/** @type {Record<string, unknown>} */
	props_def;
	/** @type {string} */
	slot_def;

	/** @param {string} name */
	constructor(name) {
		this.name = name;
	}

	label() {
		return 'widget:' + this.name;
	}
}

/** @param {Widget} widget */
export function describe(widget) {
	return [
		widget.label(),
		typeof widget.props_def,
		'props_def' in widget,
		'slot_def' in widget,
		Object.keys(widget).join(','),
	].join('|');
}
